mapper.select:
SELECT t.* FROM ( SELECT e.id journal_entry_id, e.journal_sequence, e.posting_date, e.entry_type, l.line_no, l.entry_side, l.amount, SUM(CASE WHEN l.entry_side = a.normal_side THEN l.amount ELSE -l.amount END) OVER (ORDER BY e.journal_sequence, l.line_no) balance_after, i.instruction_type, i.origin_type, i.source_system, i.source_event_key, m.adjustment_no, CASE WHEN i.origin_type = 'ACCOUNT_POSTING' THEN CAST(i.source_event_key AS UNSIGNED) END account_posting_id, CASE WHEN i.origin_type = 'ACCOUNT_POSTING' THEN i.source_version END account_posting_sequence FROM t_journal_line l JOIN t_journal_entry e ON e.id = l.journal_entry_id JOIN t_ledger_account a ON a.id = l.account_id JOIN t_accounting_instruction i ON i.id = e.instruction_id LEFT JOIN t_manual_adjustment m ON m.id = i.manual_adjustment_id WHERE l.account_id = #{accountId} ) t
AND t.posting_date >= #{from} AND t.posting_date <= #{to}
ORDER BY t.journal_sequence, t.line_no LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM t_journal_line l
JOIN t_journal_entry e ON e.id = l.journal_entry_id
WHERE l.account_id = #{accountId}
AND e.posting_date >= #{from}
AND e.posting_date <= #{to}
